package com.bananalab.lite;
import android.content.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import org.json.*;
final class MethodLab{
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-method-lab",0);}
 static void restore(Context c){try{JSONObject model=new JSONObject(prefs(c).getString("model","{}"));MethodRanker.validate(model);MethodRanker.model=model;}catch(Exception e){MethodRanker.model=new JSONObject();}}
 static JSONObject experience(Context c)throws Exception{return new JSONObject().put("version",1).put("model",new JSONObject(prefs(c).getString("model","{}"))).put("cases",new JSONArray(prefs(c).getString("cases","[]")));}
 static void validateExperience(JSONObject data)throws Exception{RuntimeProgram.keys(data,"version","model","cases");if(data.getInt("version")!=1)throw new IOException("Aprendizaje incompatible.");MethodRanker.validate(data.getJSONObject("model"));JSONArray rows=data.getJSONArray("cases");if(rows.length()>32)throw new IOException("Demasiados ejemplos.");Set<String> ids=new HashSet<>();for(MethodProgram p:MethodProgram.grammar())ids.add(p.id());for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);RuntimeProgram.keys(row,"instruction","family","program","verified");if(row.getString("instruction").length()>200||!row.getBoolean("verified")||!ids.contains(row.getString("program"))||!row.getString("family").matches("array|text|turn"))throw new IOException("Ejemplo inválido.");}}
 static void importExperience(Context c,JSONObject data)throws Exception{validateExperience(data);if(!prefs(c).contains("model")&&!prefs(c).contains("cases")){if(!prefs(c).edit().putString("model",data.getJSONObject("model").toString()).putString("cases",data.getJSONArray("cases").toString()).commit())throw new IOException("No pude recuperar los pesos.");restore(c);}}
 static void learn(Context c,String instruction,MethodProgram program)throws Exception{JSONArray old=new JSONArray(prefs(c).getString("cases","[]")),next=new JSONArray();for(int i=Math.max(0,old.length()-31);i<old.length();i++)if(!old.getJSONObject(i).getString("instruction").equals(instruction))next.put(old.getJSONObject(i));next.put(new JSONObject().put("instruction",instruction).put("family",program.family).put("program",program.id()).put("verified",true));JSONObject model=MethodRanker.train(next);if(!prefs(c).edit().putString("model",model.toString()).putString("cases",next.toString()).commit())throw new IOException("No pude guardar el ranking.");MethodRanker.model=model;}
 static Method method(Context c,JSONObject row)throws Exception{MethodProgram program=MethodProgram.read(row.getJSONObject("program"));if(!JavaMethodEditor.hash(program.source()).equals(row.getString("sourceHash")))throw new IOException("La fuente candidata cambió.");File jar=new File(row.getString("jar"));if(!jar.getCanonicalPath().startsWith(OnDeviceJava.home(c).getCanonicalPath()+File.separator)||jar.canWrite()||!ProjectRuntime.digest(jar).equals(row.getString("jarHash")))throw new IOException("El código compilado cambió.");return OnDeviceJava.load(c,jar).getClassLoader().loadClass("com.bananalab.patch.JavaMethodCandidate").getMethod("run",String.class);}
 static String create(Context c,String request)throws Exception{String instruction=ChatLanguage.normalize(request);MethodProgram goal=MethodProgram.request(instruction),selected=null;int attempts=0;StringBuilder trace=new StringBuilder();for(MethodProgram candidate:MethodRanker.order(instruction,goal.family)){attempts++;boolean pass=true;for(String input:goal.inputs(false))if(!goal.oracle(input).equals(candidate.oracle(input)))pass=false;trace.append(attempts).append(". ").append(candidate.id()).append(pass?" · pasa ejemplos visibles\n":" · contraejemplo\n");if(pass){selected=candidate;break;}}if(selected==null)throw new IOException("No encontré una solución en la gramática.");JavaProject.ensure(c);Map<String,String> sources=new LinkedHashMap<>();sources.put("BananaBehavior.java",JavaPatchPolicy.BASE);sources.put("JavaMethodCandidate.java",selected.source());OnDeviceJava.Build build=OnDeviceJava.compileSources(c,sources);JSONObject spec=new JSONObject().put("program",selected.json()).put("goal",goal.json());android.os.Bundle proof=JavaTrial.request(c,build.jar,spec.toString(),"method",goal.inputs(false).length+goal.inputs(true).length);JavaProject.stage(c,"JavaAlgorithm.java",selected.core());JSONObject row=new JSONObject().put("program",selected.json()).put("goal",goal.json()).put("instruction",instruction).put("sourceHash",JavaMethodEditor.hash(selected.source())).put("jar",build.jar.getAbsolutePath()).put("jarHash",ProjectRuntime.digest(build.jar)).put("tests",proof.getInt("samples")).put("pid",proof.getInt("pid")).put("trace",trace.toString()).put("attempts",attempts);if(!prefs(c).edit().putString("candidate",row.toString()).commit())throw new IOException("No pude guardar el candidato.");String learned;try{learn(c,instruction,selected);learned=" Ajusté el ranking propio reteniendo los ejemplos verificados.";}catch(Exception e){learned=" Conservé el ranking anterior.";}return "Generé JavaAlgorithm.java#process.\nBúsqueda: "+attempts+" candidatos; compilación real y"+proof.getInt("samples")+" casos ejecutados en otro proceso: "+goal.inputs(false).length+" visibles y"+goal.inputs(true).length+" reservados. Los reservados no orientaron la búsqueda.\n"+selected.body()+"\nLa copia está preparada; probá ‘prueba mi metodo: …’. Para instalarla en el código principal: ‘reconstruye mi apk’ → Banana.apk."+learned;}
 static BananaEngine.Result handle(Context c,String input)throws Exception{String q=ChatLanguage.normalize(input);boolean create=q.startsWith("genera metodo java "),test=q.startsWith("prueba mi metodo "),run=q.startsWith("ejecuta mi metodo "),graph=q.equals("analiza proyecto java")||q.startsWith("analiza dependencias java ");if(!(create||test||run||graph||q.matches("nucleo programador|estado nucleo programador|ver mi metodo|repara mi metodo|repara mi algoritmo")))return null;JavaChat.owner=Thread.currentThread();try{String text;if(create){int at=input.indexOf(':');if(at<0)throw new IllegalArgumentException("Usá genera metodo java: suma los positivos de una lista");text=create(c,input.substring(at+1).trim());}else if(q.startsWith("repara mi")){JSONObject row=new JSONObject(prefs(c).getString("candidate","{}"));text="Reparación por nueva búsqueda y pruebas:\n"+create(c,row.getString("instruction"));}else if(test){JSONObject row=new JSONObject(prefs(c).getString("candidate","{}"));MethodProgram program=MethodProgram.read(row.getJSONObject("program"));if(!JavaProject.source(c,"JavaAlgorithm.java").equals(program.core()))throw new IOException("La copia difiere del candidato. Usá repara mi metodo.");String value=input.substring(input.indexOf(':')+1).trim();if(value.length()>1024)throw new IllegalArgumentException("Entrada demasiado larga.");text="Resultado del candidato: "+method(c,row).invoke(null,value);}else if(run){if(JavaAlgorithm.kind().equals("none"))text="El método instalado sigue siendo el original. Generá, reconstruí Banana.apk e instalá la actualización.";else{String value=input.substring(input.indexOf(':')+1).trim();if(value.length()>1024)throw new IllegalArgumentException("Entrada demasiado larga.");text="Resultado del núcleo instalado: "+JavaAlgorithm.process(value)+"\nVersión del método: "+JavaAlgorithm.version();}}else if(graph){String file=q.startsWith("analiza dependencias java ")?input.trim().substring("analiza dependencias java ".length()).trim():null;if(file!=null)JavaSourceEdit.filename(file);text=CoreBuild.graph(c,file);}else if(q.equals("ver mi metodo")){String raw=prefs(c).getString("candidate","");text=raw.isEmpty()?"Sin candidato; instalado: "+JavaAlgorithm.version():new JSONObject(raw).getString("trace")+"\n"+ProjectReplacementSpec.body(JavaProject.source(c,"JavaAlgorithm.java"),"process");}else text="Núcleo programador propio\n• genera metodo java: suma los positivos de una lista\n• genera metodo java: invierte texto en minusculas\n• genera metodo java: alterna turnos desde el ultimo personaje\n• prueba mi metodo: -3,2,5\n• ver mi metodo / repara mi metodo\n• ejecuta mi metodo: … usa classes.dex instalado\n• analiza proyecto java / analiza dependencias java JavaAlgorithm.java\n\nLa gramática compone filtros, acumuladores, texto y turnos; un ranking propio aprende de soluciones comprobadas. No genera Java libre.\nCasos aprendidos: "+new JSONArray(prefs(c).getString("cases","[]")).length()+" · instalado: "+JavaAlgorithm.version()+"\nReconstruye mi apk produce Banana.apk, actualización de esta misma app. Se rechazan lambdas o cambios de ABI incompatibles.";return MobileCore.say(c,text,"app_ajuste");}catch(Exception e){return MobileCore.say(c,"Conservé el núcleo instalado: "+AndroidRepair.summary(e),"app_ajuste");}finally{JavaChat.owner=null;JavaChat.progress="";}}
}
